const ledgerAccountTotals = `-- name: LedgerAccountTotals :many
SELECT account, (coalesce(sum(amount_minor) FILTER (WHERE direction = 'debit'), 0) -
        coalesce(sum(amount_minor) FILTER (WHERE direction = 'credit'), 0))::bigint AS balance
FROM ledger_entries WHERE org_id IS NOT DISTINCT FROM $1 OR $1::uuid IS NULL
GROUP BY account ORDER BY account
`

type LedgerAccountTotalsRow struct {
	Account string
	Balance int64
}

// tenant: system - the ledger check and finance views.
func (q *Queries) LedgerAccountTotals(ctx context.Context, orgID *uuid.UUID) ([]LedgerAccountTotalsRow, error) {
	rows, err := q.db.Query(ctx, ledgerAccountTotals, orgID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []LedgerAccountTotalsRow
	for rows.Next() {
		var i LedgerAccountTotalsRow
		if err := rows.Scan(&i.Account, &i.Balance); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const ledgerBalance = `-- name: LedgerBalance :one
SELECT (coalesce(sum(amount_minor) FILTER (WHERE direction = 'debit'), 0) -
        coalesce(sum(amount_minor) FILTER (WHERE direction = 'credit'), 0))::bigint AS balance
FROM ledger_entries WHERE ($1::uuid IS NULL OR org_id = $1) AND account = $2
`

type LedgerBalanceParams struct {
	OrgID   *uuid.UUID
	Account string
}

// tenant: system - balances of an org the caller resolved (debits minus
// credits); with no org, the account across all of them.
func (q *Queries) LedgerBalance(ctx context.Context, arg LedgerBalanceParams) (int64, error) {
	row := q.db.QueryRow(ctx, ledgerBalance, arg.OrgID, arg.Account)
	var balance int64
	err := row.Scan(&balance)
	return balance, err
}

const ledgerTotals = `-- name: LedgerTotals :one
SELECT coalesce(sum(amount_minor) FILTER (WHERE direction = 'debit'), 0)::bigint AS debits,
       coalesce(sum(amount_minor) FILTER (WHERE direction = 'credit'), 0)::bigint AS credits,
       count(DISTINCT txn_id)::int AS txns
FROM ledger_entries
`

type LedgerTotalsRow struct {
	Debits  int64
	Credits int64
	Txns    int32
}

// tenant: system - the ledger's invariant check.
func (q *Queries) LedgerTotals(ctx context.Context) (LedgerTotalsRow, error) {
	row := q.db.QueryRow(ctx, ledgerTotals)
	var i LedgerTotalsRow
	err := row.Scan(&i.Debits, &i.Credits, &i.Txns)
	return i, err
}

